tool.output_format:
Returns: {
  "path": string,         // Resolved absolute path
  "entries": [
    {
      "name": string,
      "type": "file" | "directory" | "symlink",
      "size_bytes": integer,
      "permissions": string,
      "modified": string,  // ISO timestamp
      "owner": string
    }
  ],
  "total_count": integer,
  "truncated": boolean
}
